"""Independently authored test answers 0..4; no solution records read."""
import json
from pathlib import Path

ANSWERS = [
('2063/A', 'The minimal segments are [1,1] and [x,x+1] for x>=2. Every longer interval contains an adjacent coprime pair, while singleton x>1 is not coprime. Thus answer is r-l except the interval [1,1], whose answer is 1. O(1) per case.', r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){long long l,r;cin>>l>>r;cout<<(l==1&&r==1?1:r-l)<<'\n';}}'''),
('2063/B', 'A reversed subsequence can import values into the target interval from only one side: outer left/right chosen indices pair with each other before either can pair with an interior index. Internal swaps do not affect the sum. On either side, any chosen k interior values can be exchanged with k external values by reversing their combined subsequence. Therefore take the smaller of the sums of the r-l+1 smallest values in prefix [1,r] and suffix [l,n]. O(n log n) time, O(n) memory.', r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,l,r;cin>>n>>l>>r;vector<long long>a(n);for(auto &x:a)cin>>x;vector<long long>p(a.begin(),a.begin()+r),s(a.begin()+l-1,a.end());sort(p.begin(),p.end());sort(s.begin(),s.end());long long x=0,y=0;for(int i=0;i<r-l+1;i++){x+=p[i];y+=s[i];}cout<<min(x,y)<<'\n';}}'''),
('2063/C', 'Removing u creates deg(u) components; removing v then adds deg(v)-1 minus one if adjacent to u. Maximize deg(u)+deg(v)-1-adjacent(u,v). Maintain all degrees in a multiset. For each u temporarily remove its degree and decrease each neighbor degree by one. The maximum remaining value gives its best v. Restore after recording. Each edge is updated O(1) times overall, so O(n log n) time and O(n) space.', r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<vector<int>>g(n);for(int i=1,u,v;i<n;i++){cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}vector<int>d(n);multiset<int>s;for(int i=0;i<n;i++){d[i]=g[i].size();s.insert(d[i]);}int ans=0;for(int u=0;u<n;u++){s.erase(s.find(d[u]));for(int v:g[u]){s.erase(s.find(d[v]));s.insert(d[v]-1);}ans=max(ans,d[u]+*s.rbegin()-1);for(int v:g[u]){s.erase(s.find(d[v]-1));s.insert(d[v]);}s.insert(d[u]);}cout<<ans<<'\n';}}'''),
('2063/D', 'Each triangle uses two points from one line and one from the other, and its area equals the horizontal separation of the pair. For x pairs on lower line and k-x on upper, feasibility requires max(0,2k-m)<=x<=min(k,n-k). Maximum separation sums come from pairing opposite sorted extremes; let A[x],B[y] be their prefix sums. Optimize A[x]+B[k-x] on the feasible interval. The marginal differences are decreasing, so the function is discretely concave; binary-search the peak. kmax=min(n,m,(n+m)/3). O((n+m)log(n+m)) time and O(n+m) space.', r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m;cin>>n>>m;vector<ll>a(n),b(m);for(auto&x:a)cin>>x;for(auto&x:b)cin>>x;sort(a.begin(),a.end());sort(b.begin(),b.end());vector<ll>A(n/2+1),B(m/2+1);for(int i=1;i<=n/2;i++)A[i]=A[i-1]+a[n-i]-a[i-1];for(int i=1;i<=m/2;i++)B[i]=B[i-1]+b[m-i]-b[i-1];int K=min({n,m,(n+m)/3});cout<<K<<'\n';for(int k=1;k<=K;k++){int lo=max({0,2*k-m,k-m/2}),hi=min({k,n-k,n/2});auto val=[&](int x){return A[x]+B[k-x];};while(lo<hi){int mid=(lo+hi)/2;if(val(mid)<=val(mid+1))lo=mid+1;else hi=mid;}cout<<val(lo)<<(k==K?'\n':' ');}if(K==0)cout<<'\n';}}'''),
('2063/E', 'For a good pair, triangle inequalities give 2*min(depth(u)-depth(lca),depth(v)-depth(lca))-1 choices. For ancestor pairs the minimum difference is zero. Sum min(depth(u),depth(v)) over all unordered pairs using sorted depths; subtract sum depth(lca). At each vertex, the number of pairs whose LCA is that vertex equals C(subtree_size,2) minus the sum of C(child_subtree_size,2). Finally subtract the count of good pairs, C(n,2)-sum(depth). Answer is 2*(sumMinDepth-sumLcaDepth)-goodPairs. Iterative traversal avoids stack overflow. O(n log n) time and O(n) space.', r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;ll pairs(ll n){return n*(n-1)/2;}int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<vector<int>>g(n);for(int i=1,u,v;i<n;i++){cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}vector<int>par(n,-1),dep(n),order{0};for(int i=0;i<(int)order.size();i++){int u=order[i];for(int v:g[u])if(v!=par[u]){par[v]=u;dep[v]=dep[u]+1;order.push_back(v);}}vector<ll>sz(n,1);ll lcaSum=0,depthSum=0;for(int i=n-1;i>=0;i--){int u=order[i];ll sub=0;for(int v:g[u])if(par[v]==u){sz[u]+=sz[v];sub+=pairs(sz[v]);}lcaSum+=(pairs(sz[u])-sub)*dep[u];depthSum+=dep[u];}sort(dep.begin(),dep.end());ll minSum=0;for(int i=0;i<n;i++)minSum+=(ll)dep[i]*(n-1-i);cout<<2*(minSum-lcaSum)-(pairs(n)-depthSum)<<'\n';}}''')]

if __name__ == '__main__':
    p = Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a', encoding='utf-8') as out:
        for ident, explanation, code in ANSWERS:
            out.write(json.dumps({'id': ident, 'split': 'test', 'author': 'current chat assistant',
                'status': 'authored', 'explanation': explanation, 'cpp_code': code,
                'validation': 'not executed'}, ensure_ascii=False)+'\n')
